package com.acttub.actingapi.consent;
import static org.assertj.core.api.Assertions.*; import java.nio.file.*; import java.util.concurrent.*; import com.acttub.actingapi.support.PostgresContainerSupport; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.DefaultApplicationArguments; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.core.io.ResourceLoader; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.*;
@SpringBootTest(properties="JWT_SECRET=test-secret") class ConsentPublisherIT {@DynamicPropertySource static void db(DynamicPropertyRegistry r){String n=PostgresContainerSupport.createDatabaseName("consent_publish");r.add("spring.datasource.url",()->PostgresContainerSupport.jdbcUrlFor(n));r.add("spring.datasource.username",PostgresContainerSupport.POSTGRES::getUsername);r.add("spring.datasource.password",PostgresContainerSupport.POSTGRES::getPassword);}@Autowired JdbcTemplate jdbc;@Autowired ConsentDocumentPublisher publisher;
    @Autowired ObjectMapper mapper;@Autowired ResourceLoader resources;
    @Test void emptyDatabaseBootPublishesWholeManifestAndRepeatIsIdempotent()throws Exception{assertThat(jdbc.queryForList("SELECT type::text,version,title,required,length(body) body_length FROM consent_documents ORDER BY type::text")).hasSize(3).allSatisfy(row->{assertThat(row.get("required")).isEqualTo(true);assertThat(((Number)row.get("body_length")).intValue()).isPositive();});assertThat(publisher.publish()).isZero();}
    @Test void missingOrInvalidManifestNeverStopsStartup(@TempDir Path dir)throws Exception{ConsentDocumentPublisher missing=new ConsentDocumentPublisher(jdbc,mapper,resources,dir.resolve("missing").toString());assertThatCode(()->missing.run(new DefaultApplicationArguments())).doesNotThrowAnyException();Files.writeString(dir.resolve("manifest.json"),"{");ConsentDocumentPublisher invalid=new ConsentDocumentPublisher(jdbc,mapper,resources,dir.toString());assertThatCode(()->invalid.run(new DefaultApplicationArguments())).doesNotThrowAnyException();}
    @Test void concurrentPublishIgnoresOnlyTheNamedUniqueRace()throws Exception{jdbc.update("DELETE FROM consent_documents");ConsentDocumentPublisher other=new ConsentDocumentPublisher(jdbc,mapper,resources,"");ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Integer>a=pool.submit(publisher::publish),b=pool.submit(other::publish);assertThat(a.get()+b.get()).isBetween(3,6);assertThat(jdbc.queryForObject("SELECT count(*) FROM consent_documents",Integer.class)).isEqualTo(3);}finally{pool.shutdownNow();}}
}
